INSERT INTO valoraciones.valoraciones (id_valoracion, id_historia, id_fisioterapeuta, nombre_fisioterapeuta, tipo, estado, version_ficha, contenido, datos_personales, version, fecha_inicio, fecha_finalizacion, fecha_actualizacion) VALUES ('b73451d2-22b9-44cf-87af-b6ffea037cf3', 'ab76a185-823f-4972-9938-9d40a735f495', '53b61f25-d570-4567-8100-1f647e135527', 'Daniela Ortega', 'TRAUMA_ADULTO', 'FINALIZADA', 1, '{"s2.fase": "Postoperatoria", "s3.sueno": "Conservado", "s11.fecha": "2026-11-22", "s3.sintomas": ["Inestabilidad"], "s2.mecanismo": ["Otro"], "s3.patron_24_h": ["Mecánico"], "s2.antecedentes": ["Quirúrgicos"], "s9.deficiencias": "Examen físico", "s6.6_1_inspeccion": ["Postura/alineación", "Cicatriz/herida", "Órtesis/ayudas"], "s1.centro_servicio": "dvdv", "s1.medico_tratante": "Chespirito", "s10.intervenciones": ["Ejercicio"], "s10.dosificacion.rpe": "1", "s10.objetivo_general": "Examen físico", "s9.impresion_clinica": "Examen físico", "s10.dosificacion.reps": "1", "s10.objetivos_smart.1": "fr", "s10.objetivos_smart.2": "cvrdv", "s10.objetivos_smart.3": "crcv", "s3.inicio_y_evolucion": "Las ciudades cambian cada día a medida que las personas buscan nuevos espacios para vivir, trabajar y compartir. En las calles transitadas se mezclan los pasos apurados de quienes van a su oficina con el ritmo pausado de quienes caminan sin prisa por la tarde. Las plazas funcionan como puntos de encuentro donde conversan vecinos de distintas edades, leen los estudiantes y descansan quienes recorren el barrio a pie. A veces basta observar una fachada antigua, un árbol frondoso o una librería pequeña para notar detalles que suelen pasar desapercibidos en la rutina diaria. Escribir con atención permite ordenar las ideas, observar mejor el entorno y dar forma a pensamientos que nacen de experiencias sencillas. Cada palabra aporta matices y ayuda a construir un relato claro, cercano y fácil de leer para cualquier persona que se detenga a recorrer estas líneas con calma. Así, un texto breve puede reunir escenas cotidianas, reflexiones simples y una mirada atenta sobre lo que ocurre alrededor", "s3.dolor_nrs_0_10.peor": "2", "s6.6_1_inspeccion.otro": "lflrfrlgb", "s10.dosificacion.series": "1", "s2.fecha_lesion_cirugia": "2026-11-21", "s3.dolor_nrs_0_10.mejor": "2", "s2.medicamentos_alergias": "Las ciudades cambian cada día a medida que las personas buscan nuevos espacios para vivir, trabajar y compartir. En las calles transitadas se mezclan los pasos apurados de quienes van a su oficina con el ritmo pausado de quienes caminan sin prisa por la tarde. Las plazas funcionan como puntos de encuentro donde conversan vecinos de distintas edades, leen los estudiantes y descansan quienes recorren el barrio a pie. A veces basta observar una fachada antigua, un árbol frondoso o una librería pequeña para notar detalles que suelen pasar desapercibidos en la rutina diaria. Escribir con atención permite ordenar las ideas, observar mejor el entorno y dar forma a pensamientos que nacen de experiencias sencillas. Cada palabra aporta matices y ayuda a construir un relato claro, cercano y fácil de leer para cualquier persona que se detenga a recorrer estas líneas con calma. Así, un texto breve puede reunir escenas cotidianas, reflexiones simples y una mirada atenta sobre lo que ocurre alrededor", "s3.dolor_nrs_0_10.actual": "2", "s9.factores_contextuales": "Examen físico", "s10.dosificacion.descanso": "1", "s10.fecha_de_reevaluacion": "2026-11-30", "s10.programa_domiciliario": "Examen físico", "s3.alicia_socrates.inicio": "1", "s3.objetivos_del_paciente": "Dolor NRS 0–10", "s10.dosificacion.intensidad": "1", "s2.actividad_fisica_trabajo": "Las ciudades cambian cada día a medida que las personas buscan nuevos espacios para vivir, trabajar y compartir. En las calles transitadas se mezclan los pasos apurados de quienes van a su oficina con el ritmo pausado de quienes caminan sin prisa por la tarde. Las plazas funcionan como puntos de encuentro donde conversan vecinos 